<?php
require_once __DIR__ . '/auth.php';
$id = (int)($_GET['id'] ?? 0);
if ($id <= 0) { header('Location: users.php'); exit; }
$stmt = $conn->prepare("SELECT e.*, u.role, u.last_login FROM employees e LEFT JOIN users u ON u.employee_id=e.id WHERE e.id=? LIMIT 1");
$stmt->bind_param('i', $id); $stmt->execute(); $employee = $stmt->get_result()->fetch_assoc();
if (!$employee) { header('Location: users.php'); exit; }
$status = $employee['employment_status'] === 'Inactive' ? 'Inactive' : 'Active';
$att = $conn->prepare("SELECT attendance_date,time_in,time_out,total_hours,ot_hours,status FROM attendance WHERE employee_id=? ORDER BY attendance_date DESC LIMIT 5"); $att->bind_param('i',$id); $att->execute(); $attendance=$att->get_result()->fetch_all(MYSQLI_ASSOC);
$leave = $conn->prepare("SELECT leave_type,date_from,date_until,status FROM leave_requests WHERE employee_id=? ORDER BY date_from DESC LIMIT 5"); $leave->bind_param('i',$id); $leave->execute(); $leaves=$leave->get_result()->fetch_all(MYSQLI_ASSOC);
$pay = $conn->prepare("SELECT payroll_period_start,payroll_period_end,net_pay FROM payslips WHERE employee_id=? ORDER BY payroll_period_end DESC LIMIT 5"); $pay->bind_param('i',$id); $pay->execute(); $payslips=$pay->get_result()->fetch_all(MYSQLI_ASSOC);
?>
