<div class="col-12 col-xl-8"><div class="panel mb-3"><div class="panel-header"><div><h2 class="h5 mb-1 section-title"><i class="bi bi-person-lines-fill"></i><span>Account Overview</span></h2><p class="text-muted mb-0">Current role, status, and account access.</p></div></div><div class="row g-3"><div class="col-md-4"><div class="mini-card"><span>Role</span><strong><?php echo e(ucfirst($employee['role'] ?? 'employee')); ?></strong></div></div><div class="col-md-4"><div class="mini-card"><span>Last Login</span><strong><?php echo $employee['last_login'] ? e(date('M j, Y g:i A', strtotime($employee['last_login']))) : 'Never'; ?></strong></div></div><div class="col-md-4"><div class="mini-card"><span>Status</span><strong><?php echo e($status); ?></strong></div></div></div></div>
<div class="panel"><div class="panel-header"><div><h2 class="h5 mb-1 section-title"><i class="bi bi-activity"></i><span>Workforce Activities</span></h2><p class="text-muted mb-0">Latest attendance, leave, and payroll records for this employee.</p></div></div>
<div class="table-responsive mb-4"><table class="table align-middle mb-0"><thead><tr><th colspan="5">Recent Attendance</th></tr><tr><th>Date</th><th>Time In</th><th>Time Out</th><th>Hours</th><th>Status</th></tr></thead><tbody><?php if(!$attendance): ?><tr><td colspan="5" class="text-muted">No attendance records yet.</td></tr><?php else: foreach($attendance as $a): ?><tr><td><?php echo e(date('M j, Y',strtotime($a['attendance_date']))); ?></td><td><?php echo e($a['time_in'] ?: '—'); ?></td><td><?php echo e($a['time_out'] ?: '—'); ?></td><td><?php echo e($a['total_hours']); ?></td><td><?php echo e($a['status']); ?></td></tr><?php endforeach; endif; ?></tbody></table></div>
<div class="table-responsive mb-4"><table class="table align-middle mb-0"><thead><tr><th colspan="4">Recent Leave</th></tr><tr><th>Type</th><th>Start</th><th>End</th><th>Status</th></tr></thead><tbody><?php if(!$leaves): ?><tr><td colspan="4" class="text-muted">No leave requests yet.</td></tr><?php else: foreach($leaves as $l): ?><tr><td><?php echo e($l['leave_type']); ?></td><td><?php echo e(date('M j, Y',strtotime($l['date_from']))); ?></td><td><?php echo e(date('M j, Y',strtotime($l['date_until']))); ?></td><td><?php echo e($l['status']); ?></td></tr><?php endforeach; endif; ?></tbody></table></div>
<div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th colspan="4">Recent Payslips</th></tr><tr><th>Period</th><th>Net Pay</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if(!$payslips): ?><tr><td colspan="4" class="text-muted">No payslips yet.</td></tr><?php else: foreach($payslips as $p): ?><tr><td><?php echo e(date('M j, Y',strtotime($p['payroll_period_start']))).' - '.e(date('M j, Y',strtotime($p['payroll_period_end']))); ?></td><td>₱<?php echo e(number_format((float)$p['net_pay'],2)); ?></td><td><span class="badge text-bg-success">Released</span></td><td><a class="btn btn-light btn-sm" href="payroll.php">View Payroll</a></td></tr><?php endforeach; endif; ?></tbody></table></div>
